#!/usr/bin/env python3
"""Bounded public research captures, with exact source metadata and compressed bytes."""
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
import datetime,gzip,hashlib,json,requests,subprocess,tempfile
ROOT=Path(__file__).resolve().parent
URLS={'ket-election': 'https://ket.org/election/', 'ket-primary-release': 'https://ket.org/pressroom/release/primary-2026-on-ket-offers-live-results-and-analysis-on-primary-election/', 'wkyt-home': 'https://www.wkyt.com/', 'wdrb-home': 'https://www.wdrb.com/', 'wkythome-paducah': 'https://www.wpsdlocal6.com/', 'state-results-2026': 'https://elect.ky.gov/results/2020-2029/Pages/2026.aspx', 'state-primary-results': 'https://vrsws.sos.ky.gov/liveresults/?id=2026', 'nyt-elections': 'https://www.nytimes.com/section/politics/elections', 'ket-primary-ap': 'https://interactives.apelections.org/election-results/customers/layouts/organization-layouts/published/73761/28480.html', 'wkyt-results': 'https://www.wkyt.com/politics/election-results/', 'sbe-2024-results-parent': 'https://elect.ky.gov/results/2020-2029/Pages/2024.aspx', 'sbe-2022-results-parent': 'https://elect.ky.gov/results/2020-2029/Pages/2022.aspx', 'sbe-2020-results-parent': 'https://elect.ky.gov/results/2020-2029/Pages/2020.aspx', 'sbe-2024-amended-original': 'https://elect.ky.gov/results/2020-2029/Documents/2024%20General%20Election%20Certification%20as%20Amended%20on%20December%209th%202024.pdf', 'sbe-2020-original': 'https://elect.ky.gov/results/2020-2029/Documents/2020%20General%20Election%20Results.pdf', 'sbe-2020-estill-native-original': 'https://elect.ky.gov/results/2020-2029/PublishingImages/2020General/61657_20201211_RECAP.pdf', 'sbe-2020-lyon-native-original': 'https://elect.ky.gov/results/2020-2029/PublishingImages/2020General/61002_20201118_RECAP.pdf', 'jefferson-2020-native-original': 'https://elections.jeffersoncountyclerk.org/pdfs/Gen20SOVC.pdf', 'sbe-2024-amended-archive-cdx': 'https://web.archive.org/cdx/search/cdx?url=elect.ky.gov%2Fresults%2F2020-2029%2FDocuments%2F2024%20General%20Election%20Certification%20as%20Amended%20on%20December%209th%202024.pdf&output=json&filter=statuscode%3A200&collapse=digest', 'sbe-2020-archive-cdx': 'https://web.archive.org/cdx/search/cdx?url=elect.ky.gov%2Fresults%2F2020-2029%2FDocuments%2F2020%20General%20Election%20Results.pdf&output=json&filter=statuscode%3A200&collapse=digest', 'sbe-2022-original-discovery': 'https://elect.ky.gov/results/2020-2029/Documents/2022%20General%20Election%20results.pdf', 'sbe-2024-archive-20241223120817': 'https://web.archive.org/web/20241223120817id_/https://elect.ky.gov/results/2020-2029/Documents/2024%20General%20Election%20Certification%20as%20Amended%20on%20December%209th%202024.pdf', 'sbe-2024-archive-20250611004030': 'https://web.archive.org/web/20250611004030id_/https://elect.ky.gov/results/2020-2029/Documents/2024%20General%20Election%20Certification%20as%20Amended%20on%20December%209th%202024.pdf', 'sbe-2024-archive-20250920110826': 'https://web.archive.org/web/20250920110826id_/https://elect.ky.gov/results/2020-2029/Documents/2024%20General%20Election%20Certification%20as%20Amended%20on%20December%209th%202024.pdf', 'sbe-2020-archive-20201120170339': 'https://web.archive.org/web/20201120170339id_/https://elect.ky.gov/results/2020-2029/Documents/2020%20General%20Election%20Results.pdf', 'sbe-2020-archive-20250721154857': 'https://web.archive.org/web/20250721154857id_/https://elect.ky.gov/results/2020-2029/Documents/2020%20General%20Election%20Results.pdf', 'sbe-2020-archive-20250911075540': 'https://web.archive.org/web/20250911075540id_/https://elect.ky.gov/results/2020-2029/Documents/2020%20General%20Election%20Results.pdf', 'sbe-2022-archive-cdx': 'https://web.archive.org/cdx/search/cdx?url=elect.ky.gov%2Fresults%2F2020-2029%2FDocuments%2F2022%20General%20Election%20results.pdf&output=json&filter=statuscode%3A200&collapse=digest', 'sbe-2022-archive-20221223031129': 'https://web.archive.org/web/20221223031129id_/https://elect.ky.gov/results/2020-2029/Documents/2022%20General%20Election%20results.pdf', 'sbe-2022-archive-20250828092755': 'https://web.archive.org/web/20250828092755id_/https://elect.ky.gov/results/2020-2029/Documents/2022%20General%20Election%20results.pdf', 'sbe-2022-archive-20260223085144': 'https://web.archive.org/web/20260223085144id_/https://elect.ky.gov/results/2020-2029/Documents/2022%20General%20Election%20results.pdf'}
def fetch(item):
 key,url=item;row={'id':key,'url':url,'retrieved_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
 try:
  r=requests.get(url,timeout=35);path=ROOT/(key+'.html.gz');path.write_bytes(gzip.compress(r.content,mtime=0))
  row.update(status=r.status_code,final_url=r.url,raw_sha256=hashlib.sha256(r.content).hexdigest(),asset=path.name,stored_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=len(r.content),headers=dict(r.headers))
 except requests.exceptions.SSLError as e:
  row['requests_error']=str(e)
  with tempfile.TemporaryDirectory() as t:
   body=Path(t)/'body';hdr=Path(t)/'headers'
   c=subprocess.run(['curl','--silent','--show-error','--location','--max-time','35','--dump-header',str(hdr),'--output',str(body),'--write-out','%{http_code}\\n%{url_effective}',url],capture_output=True,text=True)
   row['transport']='system curl with default certificate verification'
   if c.returncode==0:
    code,final=c.stdout.split('\\n',1) if '\\n' in c.stdout else c.stdout.split('\n',1)
    raw=body.read_bytes();path=ROOT/(key+'.html.gz');path.write_bytes(gzip.compress(raw,mtime=0))
    row.update(status=int(code),final_url=final,raw_sha256=hashlib.sha256(raw).hexdigest(),asset=path.name,stored_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=len(raw),raw_headers=hdr.read_text())
   else:row['error']=c.stderr
 except requests.RequestException as e:row['error']=str(e)
 return row
if __name__=='__main__':
 rows=list(ThreadPoolExecutor(max_workers=4).map(fetch,URLS.items()));(ROOT/'manifest.json').write_text(json.dumps(rows,indent=2)+'\n')
 for r in rows:print(r['id'],r.get('status',r.get('error')))
